 [('Ben painted the door ___ . (red)','red','complemento.',None),('She calls it ___ . (ugly)','ugly','complemento.',None),('I ___ it beautiful. (find)','find','find.',None),('He ___ fighting. (hate)','hates','hate.',None)],
