Q('A1-L111','Basic conjunctions: and, but, because, or, so',
 'eu consigo ligar ideias com and, but, because, or, so e gastar dinheiro com cuidado.',
 ('Reading · An editorial',text('Spend Money, Not Stress',['I love shopping **and** I love saving. I **spend money** on food, **but** I never buy things I don’t need, **because** it makes me nervous.','Should I buy a jacket **or** a bag? I buy the jacket, **so** my bag lasts another year.'],kicker='OPINION',by='Money Matters',gloss=[('nervous','nervoso'),('jacket','jaqueta'),('last','durar'),('save','economizar')])),
 [('The writer loves shopping.','T','love shopping.'),('The writer buys everything.','F','never buy.'),('The writer buys a jacket.','T','buy the jacket.')],
 [('“nervous” means…',['nervoso','calmo','raivoso'],0,'nervous.'),('“last” (verbo) means…',['durar','terminar','passar'],0,'last.')],
 G('Conjunctions',['Palavra','Função','Exemplo'],[['**and**','adicionar','**tea and cake**'],['**but**','contraste','**cheap but good**'],['**because**','razão','**because it is cheap**'],['**or**','escolha','**tea or coffee**'],['**so**','resultado','**It rains, so I stay home.**']],'**because** + razão; **so** + resultado. Antes de **but/so** use vírgula.'),
 [('Tea ___ cake. (and)','and','adicionar.',None),('Cheap ___ good. (but)','but','contraste.',None),('I stay home ___ it rains. (because)','because','razão.',None),('It rains, ___ I stay home. (so)','so','resultado.',None)],
 ['nervous;nervoso;I feel nervous.;Fico nervoso.','jacket;jaqueta;A warm jacket.;Uma jaqueta quente.','last;durar;It lasts.;Dura.','save;economizar;Save money.;Economize dinheiro.','spend;gastar;Spend money.;Gaste dinheiro.','because;porque;Because I like it.;Porque gosto.','so;então;So I stay.;Então fico.','or;ou;Tea or coffee?;Chá ou café?'],
 ('Shopping',[('Ana','Do you want the jacket or the bag?','Quer a jaqueta ou a bolsa?'),('Leo','The jacket, because it is warm.','A jaqueta, porque é quente.'),('Ana','It is cheap, but old.','É barata, mas velha.'),('Leo','So I buy it.','Então compro.')]),
 [('Join two ideas with and/but.','Diga.','It is cheap but good.'),('Give a reason with because.','Diga.','I stay home because it rains.'),('Give a result with so.','Diga.','It rains, so I stay home.')],
 ('Write 5 sentences with and, but, because, or, so.','I like tea and cake. It is cheap but good. I stay home because it rains. Do you want tea or coffee? It rains, so I stay home.',['Usei **as 5 conjunções**','Pontuação','Frases claras'],'5 frases'),expr=[('spend money','gastar dinheiro')])
